    OpenCetRichExampleRow(
      exampleId: 'tatoeba:13556636:1582761',
      sourceId: 'tatoeba-cc-by-2.0-fr',
      englishText: 'A shepherd drove his snow-covered goat into an abandoned cave to take shelter from the blizzard.',
      chineseText: '一个牧羊人把他一身白雪的山羊赶进被遗弃的山洞躲避暴风雪。',
      englishUsername: 'LeviHighway',
